def search_files_for_keyword(base_dir, keywords):
    found = []
    for root, dirs, files in os.walk(base_dir):
        # Skip certain directories
        skip_dirs = {'site-packages', 'node_modules', '.git', 'cache'}
        if any(d in root for d in skip_dirs):
            continue

        for f in files:
            fp = os.path.join(root, f)
            try:
                with open(fp, 'r') as file:
                    content = file.read().lower()
                    for kw in keywords:
                        if kw in content:
                            mtime = os.path.getmtime(fp)
                            age_sec = int(time.time() - mtime)
                            found.append((fp, age_sec, kw))
            except Exception as e:
                pass
    return found

